pub fn check_p61970_302_dynamics_ap_con_complex_shacl_asynchronous_machine_equivalent_circuit_rotating_m_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("AsynchronousMachineEquivalentCircuit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::AsynchronousMachineEquivalentCircuit>() {
            Some(o) => o, None => continue,
        };
        if obj.base.base.damping.is_none() { continue; }
        if obj.base.base.damping.unwrap() < 0_f64 {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dyu:RotatingMachineDynamics.damping-valueRange".to_string(),
                class:       "AsynchronousMachineEquivalentCircuit".to_string(),
                property:    "RotatingMachineDynamics.damping".to_string(),
                message:     "The value is negative.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:302:DY:RotatingMachineDynamics.damping:valueRange".to_string(),
                description: "Damping torque coefficient (D) (>= 0).  A proportionality constant that, when multiplied by the angular velocity of the rotor poles with respect to the magnetic field (frequency), results in the damping torque.  This value is often zero when the sources of damping torques (generator damper windings, load damping effects, etc.) are modelled in detail.  Typical value = 0.".to_string(),
            });
        }
    }
    violations
}

