pub fn check_p61970_302_dynamics_ap_con_complex_shacl_asynchronous_machine_time_constant_reactance_rotat_etc_2(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("AsynchronousMachineTimeConstantReactance").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::AsynchronousMachineTimeConstantReactance>() {
            Some(o) => o, None => continue,
        };
        if obj.base.base.stator_leakage_reactance.is_none() || obj.xpp.is_none() { continue; }
        if !((obj.base.base.stator_leakage_reactance.unwrap() as f64) < obj.xpp.unwrap() as f64) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dyu:AsynchronousMachineTimeConstantReactance.xpp-valueRangePair".to_string(),
                class:       "AsynchronousMachineTimeConstantReactance".to_string(),
                property:    "RotatingMachineDynamics.statorLeakageReactance".to_string(),
                message:     "The value is either equal to or greater than AsynchronousMachineTimeConstantReactance.xpp.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:302:DY:AsynchronousMachineTimeConstantReactance.xpp:valueRangePair".to_string(),
                description: "Subtransient reactance (unsaturated) (X'') (> RotatingMachineDynamics.statorLeakageReactance).  Typical value = 0,2.".to_string(),
            });
        }
    }
    violations
}

