pub fn check_p61970_302_dynamics_ap_con_complex_shacl_mechanical_load_user_defined_xone(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("MechanicalLoadUserDefined").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::MechanicalLoadUserDefined>() {
            Some(o) => o, None => continue,
        };
        let mut pass_count = 0usize;
        if obj.base.asynchronous_machine_dynamics.is_some() { pass_count += 1; }
        if obj.base.synchronous_machine_dynamics.is_some() { pass_count += 1; }
        if pass_count != 1 {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dyu:MechanicalLoadDynamics".to_string(),
                class:       "MechanicalLoadUserDefined".to_string(),
                property:    "C:302:DY:MechanicalLoadDynamics:associationsCondition".to_string(),
                message:     "Required association to either SynchronousMachineDynamics or to AsynchronousMachineDynamics is missing.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:302:DY:MechanicalLoadDynamics:associationsCondition".to_string(),
                description: "MechanicalLoadDynamics shall have either an association to SynchronousMachineDynamics or to AsynchronousMachineDynamics.".to_string(),
            });
        }
    }
    violations
}

