    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["InputSignalKind.busVoltage", "InputSignalKind.generatorElectricalPower", "InputSignalKind.generatorAcceleratingPower", "InputSignalKind.busVoltageDerivative", "InputSignalKind.rotorAngularFrequencyDeviation", "InputSignalKind.busFrequencyDeviation"];
